import java.util.Scanner;

public class Main {
    public static double absVal(double a) {
        return a < 0 ? -a : a;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int a = sc.nextInt();
        int b = sc.nextInt();
        int n = sc.nextInt();

        double minDiff = 1e100;
        int resX = 0, resY = 0;

        for (int i = 1; i <= n; i++) {
            int x = i;
            int y1 = (int) (((double) a / b) * i);
            int y0 = y1 + 1;

            double diff1 = absVal(((double) a / b) - ((double) y1 / x));
            double diff2 = absVal(((double) a / b) - ((double) y0 / x));

            if (minDiff > diff1) {
                minDiff = diff1;
                resX = y1;
                resY = x;
            }
            if (minDiff > diff2) {
                minDiff = diff2;
                resX = y0;
                resY = x;
            }
        }
        System.out.println(resX + "/" + resY);
        sc.close();
    }
}
